return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'hi_IN','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30 00:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'WordPress खातों को Active Directory या OpenLDAP से कनेक्ट करें।','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','Your directory account is suspended. Contact your site administrator.'=>'आपका डायरेक्टरी खाता निलंबित है। अपने साइट व्यवस्थापक से संपर्क करें।','The directory identity has changed. Contact your site administrator.'=>'डायरेक्टरी पहचान बदल गई है। अपने साइट व्यवस्थापक से संपर्क करें।','User data'=>'उपयोगकर्ता डेटा','Single sign-on'=>'एकल साइन-ऑन','Accounts'=>'खाते','Audit'=>'ऑडिट','Profile updates'=>'प्रोफ़ाइल अपडेट','Copy standard LDAP profile fields to existing WordPress accounts at login. Recovery accounts and super administrators are excluded.'=>'लॉगिन पर मानक LDAP प्रोफ़ाइल फ़ील्ड मौजूदा WordPress खातों में कॉपी करें। पुनर्प्राप्ति खाते और सुपर व्यवस्थापक इसमें शामिल नहीं हैं।','Update profiles at login'=>'लॉगिन पर प्रोफ़ाइल अपडेट करें','Replace names, email, and website with directory values. Empty directory values clear the field. A missing or invalid email stops the update.'=>'नाम, ईमेल और वेबसाइट को डायरेक्टरी के मानों से बदलें। डायरेक्टरी के खाली मान फ़ील्ड को साफ़ कर देते हैं। ईमेल न होने या अमान्य होने पर अपडेट रुक जाता है।','Custom user fields'=>'कस्टम उपयोगकर्ता फ़ील्ड','Copy LDAP fields, such as phone number or department, to WordPress at login. Your theme or other plugins can use these values.'=>'लॉगिन के समय LDAP फ़ील्ड, जैसे फोन नंबर या विभाग, को WordPress में कॉपी करें। आपका थीम या अन्य प्लगइन इन मानों का उपयोग कर सकते हैं।','Field mappings'=>'फ़ील्ड मैपिंग','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'प्रति पंक्ति एक मैपिंग: LDAP विशेषता:WordPress मेटा कुंजी:प्रकार। उदाहरण: %1$s। प्रकार: %2$s या %3$s।','Group roles'=>'समूह भूमिकाएँ','Set the WordPress role from LDAP groups at each login. The first matching rule applies. If no rule matches, use the default role. Recovery accounts and super administrators are excluded.'=>'हर लॉगिन पर LDAP समूहों के आधार पर WordPress भूमिका तय करें। पहला मेल खाता नियम लागू होता है। कोई नियम मेल न खाने पर डिफ़ॉल्ट भूमिका इस्तेमाल होती है। पुनर्प्राप्ति खाते और सुपर व्यवस्थापक इसमें शामिल नहीं हैं।','Group-to-role rules'=>'समूह से भूमिका के नियम','One group:role rule per line. Example: Editors:editor. Leave blank to keep current roles.'=>'हर पंक्ति में group:role प्रारूप में एक नियम लिखें। उदाहरण: Editors:editor. वर्तमान भूमिकाएँ बनाए रखने के लिए खाली छोड़ें।','Multisite membership'=>'मल्टीसाइट सदस्यता','Assign site membership and roles from directory groups. The first matching rule for each site applies. These rules replace the group role rules for network activation.'=>'डायरेक्टरी समूहों के आधार पर साइट सदस्यता और भूमिकाएँ दें। हर साइट के लिए पहला मेल खाता नियम लागू होता है। नेटवर्क पर सक्रिय करने पर ये नियम समूह भूमिका नियमों की जगह लेते हैं।','Group-to-site rules'=>'समूह से साइट के नियम','One group:site ID:role rule per line. Example: Editors:2:editor. On group removal, restore prior membership or remove a membership created by these rules. Manual role changes are kept on removal. Leave blank to stop membership updates.'=>'हर पंक्ति में group:site ID:role प्रारूप में एक नियम लिखें। उदाहरण: Editors:2:editor. समूह से हटने पर पिछली सदस्यता बहाल होती है या इन नियमों से बनाई गई सदस्यता हटती है। हटाने पर भूमिका में किए गए मैन्युअल बदलाव बने रहते हैं। सदस्यता अपडेट रोकने के लिए खाली छोड़ें।','Scheduled account import'=>'निर्धारित खाता आयात','Import directory accounts once per hour through WordPress scheduled tasks. Set a search account on Connection. Site traffic or a system task must run WordPress cron.'=>'WordPress के निर्धारित कार्यों से डायरेक्टरी खाते हर घंटे एक बार आयात करें। कनेक्शन में एक खोज खाता तय करें। साइट पर आने वाले ट्रैफ़िक या सिस्टम कार्य को WordPress cron चलाना होगा।','Enable scheduled import'=>'निर्धारित आयात चालू करें','Create accounts without a first login. Existing local accounts are excluded. No user session is created.'=>'पहले लॉगिन के बिना खाते बनाएँ। मौजूदा स्थानीय खाते शामिल नहीं हैं। कोई उपयोगकर्ता सत्र नहीं बनता।','Import Base DN'=>'आयात का बेस DN','Leave blank to use the connection Base DN.'=>'कनेक्शन का बेस DN इस्तेमाल करने के लिए खाली छोड़ें।','Import groups'=>'आयात समूह','One group per line. Import users in at least one group. Leave blank to import all users below the Import Base DN. Login group restrictions also apply.'=>'हर पंक्ति में एक समूह लिखें। इनमें से कम से कम एक समूह के उपयोगकर्ता आयात होते हैं। आयात के बेस DN के अंतर्गत सभी उपयोगकर्ता आयात करने के लिए खाली छोड़ें। लॉगिन समूह की पाबंदियाँ भी लागू होती हैं।','Scheduled access removal'=>'निर्धारित पहुँच हटाना','Check managed directory accounts once per hour. A confirmed missing account, disabled AD account, changed directory identity, or failed login group rule suspends access and ends all WordPress sessions. Connection errors keep the current access state.'=>'प्रबंधित डायरेक्टरी खातों को हर घंटे एक बार जाँचें। खाते के न होने की पुष्टि, बंद AD खाता, बदली हुई डायरेक्टरी पहचान या लॉगिन समूह का नियम पूरा न होने पर पहुँच निलंबित होती है और सभी WordPress सत्र समाप्त हो जाते हैं। कनेक्शन त्रुटियों पर वर्तमान पहुँच की स्थिति बनी रहती है।','Enable scheduled access removal'=>'निर्धारित पहुँच हटाना चालू करें','Keep user data and content. Restore access after a later successful directory check. Recovery accounts and super administrators are excluded. Existing suspensions remain if the task or license stops.'=>'उपयोगकर्ता डेटा और सामग्री बनाए रखें। बाद में डायरेक्टरी की सफल जाँच के बाद पहुँच बहाल होती है। पुनर्प्राप्ति खाते और सुपर व्यवस्थापक इसमें शामिल नहीं हैं। कार्य रुकने या लाइसेंस निष्क्रिय होने पर मौजूदा निलंबन बने रहते हैं।','Custom field storage'=>'कस्टम फ़ील्ड भंडारण','Leave the defaults unless your integration uses different user meta keys.'=>'डिफ़ॉल्ट छोड़ें जब तक आपकी एकीकरण में विभिन्न उपयोगकर्ता मेटा कुंजी का उपयोग न हो।','LDAP value suffix'=>'LDAP मान उपसर्ग','Stores the LDAP value, such as phone_ldap.'=>'LDAP मान को संग्रहीत करता है, जैसे phone_ldap।','WordPress value suffix'=>'WordPress मान उपसर्ग','Stores the editable WordPress value, such as phone_wp.'=>'संपादनीय WordPress मान को संग्रहीत करता है, जैसे phone_wp।','Single sign-on (SSO)'=>'एकल साइन-ऑन (SSO)','Sign users in to WordPress after your web server authenticates them.'=>'आपके वेब सर्वर द्वारा प्रमाणीकरण के बाद उपयोगकर्ताओं को WordPress में साइन इन करें।','Enable single sign-on'=>'सिंगल साइन-ऑन सक्षम करें','Users do not need a second login for WordPress.'=>'उपयोगकर्ताओं को WordPress के लिए एक दूसरा लॉगिन की आवश्यकता नहीं है।','Configure your web server to authenticate users and set REMOTE_USER. Enter an LDAP search account on Connection.'=>'अपने वेब सर्वर को उपयोगकर्ताओं को प्रमाणीकरण करने और REMOTE_USER सेट करने के लिए कॉन्फ़िगर करें। कनेक्शन पर LDAP खोज खाता दर्ज करें।','Do not copy browser headers into REMOTE_USER. Block access that bypasses web server authentication.'=>'REMOTE_USER में ब्राउज़र हेडर कॉपी न करें। वेब सर्वर प्रमाणीकरण को बायपास करने वाली पहुंच को ब्लॉक करें।','Web server authentication'=>'वेब सर्वर प्रमाणीकरण','REMOTE_USER is present.'=>'REMOTE_USER मौजूद है।','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER गायब है। वेब सर्वर कॉन्फ़िगरेशन की जांच करें।','Audit history'=>'ऑडिट इतिहास','Record login results and account changes. Records contain event names and account IDs. Passwords, directory field values, and credentials are excluded.'=>'लॉगिन के नतीजे और खाते के बदलाव दर्ज करें। रिकॉर्ड में ईवेंट के नाम और खाता ID होते हैं। पासवर्ड, डायरेक्टरी फ़ील्ड के मान और क्रेडेंशियल शामिल नहीं हैं।','Enable audit history'=>'ऑडिट इतिहास चालू करें','Store private WordPress records. Collection is off by default. Existing records remain when collection stops.'=>'निजी WordPress रिकॉर्ड सहेजें। संग्रह डिफ़ॉल्ट रूप से बंद है। संग्रह रुकने पर मौजूदा रिकॉर्ड बने रहते हैं।','Retention (days)'=>'संग्रह अवधि (दिन)','Default: 30. Range: 1 to 3650. A daily task removes older records while collection is enabled.'=>'डिफ़ॉल्ट: 30। सीमा: 1 से 3650। संग्रह चालू रहने पर दैनिक कार्य पुराने रिकॉर्ड हटाता है।','Activate a Pro license to read or export audit history.'=>'ऑडिट इतिहास पढ़ने या निर्यात करने के लिए Pro लाइसेंस सक्रिय करें।','Export CSV'=>'CSV निर्यात करें','Latest 50 records. The export includes all retained records in this scope. Times use UTC.'=>'नवीनतम 50 रिकॉर्ड। निर्यात में इस दायरे के सभी सुरक्षित रखे गए रिकॉर्ड शामिल हैं। समय UTC में है।','Time (UTC)'=>'समय (UTC)','Event'=>'ईवेंट','Actor ID'=>'कार्रवाई करने वाले की ID','User ID'=>'उपयोगकर्ता ID','Site ID'=>'साइट ID','You do not have permission to export these records.'=>'आपको इन रिकॉर्ड को निर्यात करने की अनुमति नहीं है।','A Pro setting is not valid. Check the format and role names.'=>'एक Pro सेटिंग अमान्य है। प्रारूप और भूमिकाओं के नाम जाँचें।','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'अपडेट रोक दिया गया। LDAP लॉगिन को पुनर्स्थापित करने के लिए Simple LDAP Login Pro सक्रिय करें।','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'अपडेट अवरुद्ध: इस पैकेज में सभी Pro फ़ाइलें शामिल नहीं हैं। Free स्थापित करने के लिए पहले प्लगइन को निष्क्रिय करें। आपके स्थापित फ़ाइलें और सेटिंग्स अपरिवर्तित हैं।','WordPress could not reactivate the plugin.'=>'WordPress प्लगइन को फिर से सक्रिय नहीं कर सका।','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login को PHP 8.1 या बाद के संस्करण की आवश्यकता है।','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'प्लगइन फ़ाइलें गायब हैं। रिलीज़ ZIP से Simple LDAP Login को फिर से स्थापित करें।','You do not have permission to change these settings.'=>'इन सेटिंग्स को बदलने की अनुमति नहीं है।','The settings scope has changed. Open the settings page and try again.'=>'सेटिंग्स का दायरा बदल गया है। सेटिंग्स पृष्ठ खोलें और फिर से प्रयास करें।','You do not have permission to view these settings.'=>'इन सेटिंग्स को देखने की अनुमति नहीं है।','Network settings'=>'नेटवर्क सेटिंग्स','Site settings'=>'साइट सेटिंग्स','LDAP login settings'=>'LDAP लॉगिन सेटिंग्स','Connect to LDAP, then test a login before enabling authentication.'=>'LDAP से कनेक्ट करें, फिर प्रमाणीकरण सक्षम करने से पहले लॉगिन का परीक्षण करें।','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'LDAP लॉगिन और SSO wp-config.php में SLL_DISABLE_LDAP द्वारा अक्षम हैं।','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'आपकी सहेजी गई सेटिंग्स SSO या कस्टम उपयोगकर्ता फ़ील्ड का उपयोग करती हैं। इन सुविधाओं का उपयोग करने के लिए Simple LDAP Login Pro स्थापित करें। आपकी सेटिंग्स सुरक्षित हैं।','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'सहेजा गया LDAP खोज पासवर्ड पढ़ा नहीं जा सकता। इसे कनेक्शन टैब पर फिर से दर्ज करें।','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'PHP LDAP अनुपस्थित है। कृपया अपने होस्ट से इसे स्थापित करने के लिए कहें इससे पहले कि LDAP लॉगिन सक्षम करें।','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'LDAP पासवर्ड बिना एन्क्रिप्शन के भेजे जाते हैं। यदि आपका सर्वर समर्थन करता है तो StartTLS या LDAPS का उपयोग करें।','Save settings'=>'सेटिंग्स सहेजें','Settings on other tabs are kept.'=>'अन्य टैब पर सेटिंग्स रखी जाती हैं।','LDAP connection'=>'LDAP कनेक्शन','LDAP login'=>'LDAP लॉगिन','Enable LDAP authentication.'=>'LDAP प्रमाणीकरण सक्षम करें।','Directory type'=>'निर्देशिका प्रकार','Active Directory'=>'एक्टिव डायरेक्टरी','OpenLDAP / other LDAP directory'=>'OpenLDAP / अन्य LDAP निर्देशिका','LDAP servers'=>'LDAP सर्वर','One hostname or IP address per line. Servers are tried in order.'=>'प्रति पंक्ति एक होस्टनाम या IP पता। सर्वर क्रम में आजमाए जाते हैं।','Base DN'=>'बेस DN','Where to search for users. Example: DC=example,DC=org.'=>'उपयोगकर्ताओं के लिए खोजने का स्थान। उदाहरण: DC=example,DC=org।','Username suffix'=>'उपयोगकर्ता नाम उपसर्ग','Added to usernames without a domain. Example: @example.org.'=>'डोमेन के बिना उपयोगकर्ता नामों में जोड़ा गया। उदाहरण: @example.org।','Windows domain'=>'विंडोज डोमेन','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'संक्षिप्त डोमेन नाम, जैसे EXAMPLE। यह उपयोगकर्ता नाम उपसर्ग पर प्राथमिकता लेता है।','Connection security'=>'कनेक्शन सुरक्षा','TLS requires a trusted server certificate.'=>'TLS के लिए एक विश्वसनीय सर्वर प्रमाणपत्र की आवश्यकता होती है।','StartTLS (recommended)'=>'StartTLS (सिफारिश की गई)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'अनएन्क्रिप्टेड LDAP','Unencrypted LDAP requires permission on the Advanced tab.'=>'अनएन्क्रिप्टेड LDAP के लिए उन्नत टैब पर अनुमति की आवश्यकता होती है।','Port'=>'पोर्ट','389 for StartTLS; 636 for LDAPS.'=>'StartTLS के लिए 389; LDAPS के लिए 636।','Search subfolders'=>'उपफोल्डरों की खोज करें','Search all organizational units below the Base DN.'=>'बेस DN के नीचे सभी संगठनात्मक इकाइयों की खोज करें।','LDAP search account'=>'LDAP खोज खाता','An LDAP account with read access to users and groups.'=>'उपयोगकर्ताओं और समूहों के लिए पढ़ने की पहुंच वाला LDAP खाता।','Search account'=>'खोज खाता','LDAP bind DN or account name.'=>'LDAP बाइंड DN या खाता नाम।','Search account password'=>'खोज खाता पासवर्ड','Leave blank to keep the saved password.'=>'सहेजे गए पासवर्ड को बनाए रखने के लिए खाली छोड़ें।','Login rules'=>'लॉगिन नियम','Require LDAP passwords'=>'LDAP पासवर्ड की आवश्यकता','Block WordPress passwords except for recovery access.'=>'पुनर्प्राप्ति पहुंच के अलावा वर्डप्रेस पासवर्ड को ब्लॉक करें।','Local recovery access'=>'स्थानीय पुनर्प्राप्ति पहुंच','Selected administrators'=>'चुने हुए प्रशासक','All super administrators (legacy)'=>'सभी सुपर प्रशासक (विरासत)','All administrators (legacy)'=>'सभी प्रशासक (विरासत)','Off'=>'बंद','Choose who can use a WordPress password when LDAP passwords are required.'=>'चुनें कि कौन LDAP पासवर्ड की आवश्यकता होने पर वर्डप्रेस पासवर्ड का उपयोग कर सकता है।','Automatic account creation'=>'स्वचालित खाता निर्माण','Create a WordPress account on the first successful LDAP login.'=>'पहली सफल LDAP लॉगिन पर एक वर्डप्रेस खाता बनाएं।','Default role'=>'डिफ़ॉल्ट भूमिका','For new accounts only.'=>'केवल नए खातों के लिए।','Required groups'=>'आवश्यक समूह','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'प्रति पंक्ति एक समूह नाम। उपयोगकर्ताओं को कम से कम एक में होना चाहिए। सभी LDAP उपयोगकर्ताओं की अनुमति देने के लिए खाली छोड़ें।','Recovery accounts'=>'पुनर्प्राप्ति खाते','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'केवल चुने हुए प्रशासकों के लिए। वर्डप्रेस पासवर्ड के साथ अलग स्थानीय खातों का उपयोग करें। कई खातों का चयन करने के लिए Ctrl या Command दबाएं।','Connection options'=>'कनेक्शन विकल्प','Change these only if the default values do not work with your directory.'=>'इनमें केवल तब परिवर्तन करें जब डिफ़ॉल्ट मान आपके निर्देशिका के साथ काम न करें।','LDAP timeout (seconds)'=>'LDAP टाइमआउट (सेकंड)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'LDAP ऑपरेशन के लिए अधिकतम प्रतीक्षा। डिफ़ॉल्ट: 5 सेकंड।','Login attribute'=>'लॉगिन विशेषता','Attribute used to find users. Default: uid.'=>'उपयोगकर्ताओं को खोजने के लिए उपयोग की जाने वाली विशेषता। डिफ़ॉल्ट: uid।','Allow unencrypted LDAP'=>'अनएन्क्रिप्टेड LDAP की अनुमति दें','Allow passwords to be sent without encryption.'=>'पासवर्ड को बिना एन्क्रिप्शन के भेजने की अनुमति दें।','Group search'=>'समूह खोज','Group base DN'=>'समूह आधार DN','Leave blank to use the user Base DN.'=>'उपयोगकर्ता आधार DN का उपयोग करने के लिए खाली छोड़ें।','Group name attribute'=>'समूह नाम विशेषता','Default: cn.'=>'डिफ़ॉल्ट: cn।','Group member attribute'=>'समूह सदस्य विशेषता','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'डिफ़ॉल्ट: memberUid। यदि समूह उपयोगकर्ता DN संग्रहीत करते हैं तो member या uniqueMember का उपयोग करें।','Profile attributes'=>'प्रोफ़ाइल विशेषताएँ','LDAP attributes copied to new WordPress accounts.'=>'नए WordPress खातों में कॉपी की गई LDAP विशेषताएँ।','First name attribute'=>'पहला नाम विशेषता','Last name attribute'=>'अंतिम नाम विशेषता','Email attribute'=>'ईमेल विशेषता','Website attribute'=>'वेबसाइट विशेषता','Data retention'=>'डेटा संरक्षण','Delete settings when removing the plugin'=>'प्लगइन हटाते समय सेटिंग्स हटाएँ','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'जब WordPress प्लगइन हटाता है तो सहेजी गई सेटिंग्स और LDAP क्रेडेंशियल्स हटाएँ। उपयोगकर्ता खातों को बनाए रखें।','Test LDAP login'=>'LDAP लॉगिन का परीक्षण करें','Save your settings, then run both tests. Keep this administrator session open.'=>'अपनी सेटिंग्स सहेजें, फिर दोनों परीक्षण चलाएँ। इस व्यवस्थापक सत्र को खुला रखें।','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'परीक्षण कनेक्शन, पासवर्ड और आवश्यक समूहों की जांच करते हैं। वे खाते नहीं बनाते या उपयोगकर्ताओं को साइन इन नहीं करते।','After both tests pass, enable LDAP and try logging in from another browser.'=>'जब दोनों परीक्षण पास हो जाएँ, LDAP सक्षम करें और किसी अन्य ब्राउज़र से लॉगिन करने का प्रयास करें।','Recovery'=>'पुनर्प्राप्ति','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'यदि आप लॉक हो गए हैं, तो अपने होस्टिंग फ़ाइल प्रबंधक का उपयोग करके simple-ldap-login फ़ोल्डर का नाम बदलें। WordPress व्यवस्थापक पासवर्ड के साथ लॉगिन करें, फिर फ़ोल्डर को पुनर्स्थापित करें और सेटिंग्स को सही करें।','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'प्रमाणपत्र त्रुटियों के लिए, अपने होस्ट से विश्वसनीय LDAP प्रमाणपत्र प्राधिकरण को कॉन्फ़िगर करने के लिए कहें।','LDAP tests'=>'LDAP परीक्षण','Tests use saved settings.'=>'परीक्षण सहेजी गई सेटिंग्स का उपयोग करते हैं।','1. Test connection'=>'1. कनेक्शन का परीक्षण करें','Connect to LDAP and test the search account, if set.'=>'LDAP से कनेक्ट करें और खोज खाते का परीक्षण करें, यदि सेट किया गया हो।','Test connection'=>'कनेक्शन का परीक्षण करें','2. Test login'=>'2. लॉगिन का परीक्षण करें','Check an LDAP username, password, and group membership.'=>'LDAP उपयोगकर्ता नाम, पासवर्ड और समूह सदस्यता की जांच करें।','LDAP username'=>'LDAP उपयोगकर्ता नाम','LDAP password'=>'LDAP पासवर्ड','Settings saved.'=>'सेटिंग्स सहेजी गईं।','Connection test passed.'=>'कनेक्शन परीक्षण पास हुआ।','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'LDAP से कनेक्ट नहीं कर सकते। सर्वर, पोर्ट, TLS प्रमाणपत्र और खोज खाते की जांच करें।','LDAP login test passed. No account was created.'=>'LDAP लॉगिन परीक्षण पास हुआ। कोई खाता नहीं बनाया गया।','LDAP login test failed. Check the username, password, and required groups.'=>'LDAP लॉगिन परीक्षण विफल। उपयोगकर्ता नाम, पासवर्ड और आवश्यक समूहों की जांच करें।','Could not save settings. Check the values and try again.'=>'सेटिंग्स सहेजने में असमर्थ। मानों की जांच करें और फिर से प्रयास करें।','Connection'=>'कनेक्शन','Access'=>'पहुँच','Advanced'=>'उन्नत','Troubleshooting'=>'समस्या निवारण','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'आपका LDAP लॉगिन मान्य है, लेकिन आपको एक WordPress खाता चाहिए। अपने साइट व्यवस्थापक से संपर्क करें।','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'आपका LDAP उपयोगकर्ता नाम एक मान्य WordPress उपयोगकर्ता नाम नहीं है। अपने साइट व्यवस्थापक से संपर्क करें।','The default WordPress role is not available. Contact your site administrator.'=>'डिफ़ॉल्ट WordPress भूमिका उपलब्ध नहीं है। अपने साइट व्यवस्थापक से संपर्क करें।','Could not create your WordPress account. Contact your site administrator.'=>'आपका WordPress खाता बनाने में असमर्थ। अपने साइट व्यवस्थापक से संपर्क करें।','Use your WordPress password for this recovery account.'=>'इस पुनर्प्राप्ति खाते के लिए अपना WordPress पासवर्ड उपयोग करें।','License'=>'लाइसेंस','Get Pro'=>'प्रो प्राप्त करें','Could not check your license. Pro features remain active. Try again on the License tab.'=>'आपका लाइसेंस चेक नहीं किया जा सका। प्रो सुविधाएँ सक्रिय हैं। लाइसेंस टैब पर फिर से प्रयास करें।','Your Pro license has expired. Single sign-on and custom field updates are off. Renew your license, then select Check license on the License tab.'=>'आपका प्रो लाइसेंस समाप्त हो गया है। सिंगल साइन-ऑन और कस्टम फ़ील्ड अपडेट बंद हैं। अपना लाइसेंस नवीनीकरण करें, फिर लाइसेंस टैब पर लाइसेंस जांचें का चयन करें।','Activate a Pro license on the License tab to use single sign-on and custom user fields.'=>'सिंगल साइन-ऑन और कस्टम उपयोगकर्ता फ़ील्ड का उपयोग करने के लिए लाइसेंस टैब पर प्रो लाइसेंस सक्रिय करें।','Simple LDAP Login Pro'=>'सिंपल LDAP लॉगिन प्रो','Give staff fewer login prompts and keep user details in sync with LDAP.'=>'कर्मचारियों को कम लॉगिन प्रॉम्प्ट दें और LDAP के साथ उपयोगकर्ता विवरण को समन्वयित रखें।','Let staff open WordPress without another login prompt. Requires authentication on your web server, such as Kerberos or NTLM.'=>'कर्मचारियों को बिना किसी अन्य लॉगिन प्रॉम्प्ट के WordPress खोलने दें। आपके वेब सर्वर पर प्रमाणीकरण की आवश्यकता है, जैसे Kerberos या NTLM।','Copy phone numbers, departments, and other LDAP fields to WordPress at login. Use these values in your theme or other plugins.'=>'लॉगिन के समय फोन नंबर, विभाग और अन्य LDAP फ़ील्ड को WordPress में कॉपी करें। अपने थीम या अन्य प्लगइन में इन मानों का उपयोग करें।','View plans'=>'योजनाएँ देखें','Open checkout in a new tab'=>'नए टैब में चेकआउट खोलें','Plans and checkout use PaidCommunities. It receives your IP address and browser details.'=>'योजनाएँ और चेकआउट PaidCommunities का उपयोग करते हैं। यह आपके IP पते और ब्राउज़र विवरण प्राप्त करता है।','After purchase, install the Pro ZIP from your receipt. Your LDAP settings will stay in place.'=>'खरीद के बाद, अपनी रसीद से प्रो ZIP स्थापित करें। आपकी LDAP सेटिंग्स यथावत रहेंगी।','License status updated.'=>'लाइसेंस स्थिति अपडेट की गई।','Could not verify the license. Check your key and connection, then try again.'=>'लाइसेंस की सत्यापन नहीं हो सका। अपनी कुंजी और कनेक्शन की जांच करें, फिर फिर से प्रयास करें।','Pro license'=>'प्रो लाइसेंस','Enter the license key from your purchase receipt.'=>'अपनी खरीद रसीद से लाइसेंस कुंजी दर्ज करें।','Not activated'=>'सक्रिय नहीं किया गया','Expired'=>'समाप्त','Inactive'=>'निष्क्रिय','License status'=>'लाइसेंस स्थिति','Active'=>'सक्रिय','Data shared with PaidCommunities'=>'PaidCommunities के साथ साझा किया गया डेटा','Activation sends your license key, site domain, plugin version, and server IP address to PaidCommunities. License checks send the same site details.'=>'सक्रियकरण आपकी लाइसेंस कुंजी, साइट डोमेन, प्लगइन संस्करण, और सर्वर IP पते को PaidCommunities पर भेजता है। लाइसेंस जांचें वही साइट विवरण भेजती हैं।','License key'=>'लाइसेंस कुंजी','Activate license'=>'लाइसेंस सक्रिय करें','Deactivate license'=>'लाइसेंस निष्क्रिय करें','Check license'=>'लाइसेंस जांचें','Select a license action.'=>'एक लाइसेंस क्रिया चुनें।','Activating license…'=>'लाइसेंस सक्रिय किया जा रहा है…','Deactivating license…'=>'लाइसेंस निष्क्रिय किया जा रहा है…','License error'=>'लाइसेंस त्रुटि','License updated'=>'लाइसेंस अपडेट किया गया','Pro plans'=>'प्रो योजनाएँ','Loading plans…'=>'योजनाएँ लोड हो रही हैं…','Could not load plans. Open checkout in a new tab.'=>'योजनाएँ लोड नहीं की जा सकीं। नए टैब में चेकआउट खोलें।','LDAP login failed. Check your username and password or contact your site administrator.'=>'LDAP लॉगिन विफल। अपने उपयोगकर्ता नाम और पासवर्ड की जांच करें या अपने साइट व्यवस्थापक से संपर्क करें।','Your account is not allowed to log in to this site.'=>'आपका खाता इस साइट पर लॉग इन करने की अनुमति नहीं है।','LDAP login is unavailable. Contact your site administrator.'=>'LDAP लॉगिन उपलब्ध नहीं है। कृपया अपने साइट व्यवस्थापक से संपर्क करें।','PHP OpenSSL is required to save the LDAP search password.'=>'LDAP खोज पासवर्ड को सहेजने के लिए PHP OpenSSL की आवश्यकता है।','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'LDAP खोज पासवर्ड को पढ़ने या सहेजने में असमर्थ। कृपया इसे फिर से दर्ज करें। यदि यह जारी रहता है, तो अपने होस्ट से OpenSSL और एन्क्रिप्शन कुंजी की जांच करने के लिए कहें।','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'एक पुनर्प्राप्ति खाता चुनें, या स्थानीय पुनर्प्राप्ति पहुंच को बंद करें।','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'उन्नत टैब पर असुरक्षित LDAP की अनुमति सक्षम करें, या StartTLS या LDAPS चुनें।','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'एक कस्टम फ़ील्ड मैपिंग एक सुरक्षित या अमान्य WordPress उपयोगकर्ता मेटा कुंजी का उपयोग करती है।','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'LDAP लॉगिन सक्षम करने से पहले एक बेस DN और कम से कम एक LDAP सर्वर दर्ज करें।','WordPress could not save the settings. Try again.'=>'WordPress सेटिंग्स को सहेजने में असमर्थ। कृपया फिर से प्रयास करें।','LDAP protocol version'=>'LDAP प्रोटोकॉल संस्करण','LDAP timeout'=>'LDAP टाइमआउट','Check the submitted settings. No changes were saved.'=>'जमा की गई सेटिंग्स की जांच करें। कोई परिवर्तन सहेजे नहीं गए।','Check %s. No changes were saved.'=>'%s की जांच करें। कोई परिवर्तन सहेजे नहीं गए।']];